def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    desperate_opp = 0
    rich_opp = 0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 140:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    high_supply = supply >= 22
    low_supply = supply <= 17

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    pressure = 0
    if highest_prev >= 120:
        pressure += 3
    elif highest_prev >= 85:
        pressure += 2
    elif highest_prev >= 45:
        pressure += 1
    pressure += min(desperate_opp, 2)
    if rich_opp >= 2:
        pressure += 1

    if urgency >= 5:
        bid = max(90.0, highest_prev + 2.0)
    elif urgency >= 3:
        if high_supply:
            bid = max(42.0, avg_prev + 2.0)
        else:
            bid = max(68.0, highest_prev + 1.5)
    else:
        if pressure >= 4 and not high_supply:
            bid = 8.0 if hp >= 5 else 28.0
        elif pressure >= 3:
            bid = 18.0 if high_supply else 26.0
        elif high_supply:
            bid = max(22.0, min(38.0, avg_prev + 1.0))
        elif low_supply:
            bid = max(30.0, min(52.0, highest_prev * 0.55 + 6.0))
        else:
            bid = max(25.0, min(44.0, avg_prev + 1.5))

    if day >= 8:
        if hp <= 5:
            bid = max(bid, 60.0)
        else:
            bid = max(bid, 28.0)

    reserve_floor = 0.0
    if hp >= 6 and day <= 6:
        reserve_floor = 20.0
    max_affordable = max(0.0, budget - reserve_floor)
    if urgency >= 5:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(bid)

